.nodo-field { display: flex; flex-direction: column; gap: var(--spacing1); }

.nodo-field__label {
  font-size: 12px; line-height: 16px; font-weight: 600;
  color: var(--on-surface-variant);
}

.nodo-field__box {
  display: flex; align-items: center; gap: var(--spacing2);
  height: 56px;
  padding-inline: var(--spacing4);
  border: 1px solid var(--outline-high);
  border-radius: var(--radius-small);
  background: transparent;
  transition: border-color var(--transition-fast), border-width var(--transition-fast);
}
.nodo-field__box:hover { border-color: var(--outline); }
.nodo-field__box:focus-within {
  border-color: var(--primary);
  border-width: 2px;
  padding-inline: calc(var(--spacing4) - 1px); /* compensa el borde para no mover el contenido */
}

.nodo-field__input {
  flex: 1; min-width: 0;
  border: none; outline: none; background: transparent;
  font-family: inherit; font-size: 16px; line-height: 24px;
  color: var(--on-surface);
}
.nodo-field__input::placeholder { color: var(--on-surface-low); }

.nodo-field__icon { flex: none; color: var(--on-surface-low); }

.nodo-field__supporting {
  margin: 0;
  min-height: 16px; /* espacio reservado: evita layout shift al aparecer el error */
  font-size: 12px; line-height: 16px;
  color: var(--on-surface-variant);
}

/* Estados */
.nodo-field:has(:invalid:not(:placeholder-shown)) .nodo-field__box,
.nodo-field:has([aria-invalid="true"]) .nodo-field__box { border-color: var(--error); border-width: 2px; }
.nodo-field:has([aria-invalid="true"]) .nodo-field__label,
.nodo-field:has([aria-invalid="true"]) .nodo-field__supporting { color: var(--error); }

.nodo-field:has(:read-only) .nodo-field__box { background: var(--surface-container); border-color: var(--outline-low); }
.nodo-field:has(:disabled) .nodo-field__box { border-color: transparent; background: color-mix(in srgb, var(--on-surface) 12%, transparent); }
.nodo-field:has(:disabled) .nodo-field__label,
.nodo-field:has(:disabled) .nodo-field__supporting { color: color-mix(in srgb, var(--on-surface) 38%, transparent); }

/* Variante filled */
.nodo-field--filled .nodo-field__box { background: var(--surface-container); border-color: transparent; }

/* Tamaño small */
.nodo-field--small .nodo-field__box { height: 48px; padding-inline: var(--spacing3); }
.nodo-field--small .nodo-field__input { font-size: 14px; line-height: 20px; }

@media (prefers-reduced-motion: reduce) {
  .nodo-field__box { transition: none; }
}
